const opt = (value, label, selected) => `<option value="${esc(value)}" ${selected === value ? 'selected' : ''}>${esc(label)}</option>`;
const accountOptions = (s, v) => s.accounts.map(a => opt(a.id, a.name, v)).join('');
const assetOptions = (s, v) => s.assets.map(a => opt(a.id, `${a.symbol} — ${a.name}`, v)).join('');
const portfolioOptions = (s, v) => s.portfolios.map(a => opt(a.id, `${a.name} · ${a.platform}`, v)).join('');
const categoryOptions = (s, v, kind) => s.categories.filter(c => !kind || c.kind === kind).map(c => opt(c.id, c.name, v)).join('');
const field = (label, name, value = '', type = 'text', extra = '') => `<label class="form-field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select = (label, name, options, extra = '') => `<label class="form-field"><span>${label}</span><select name="${name}" ${extra}>${Array.isArray(options) ? options.join('') : options}</select></label>`;
const desc = (text) => `<p class="form-help">${text}</p>`;
export function formFor(s, kind, recordId) {
    const records = { movement: s.movements, account: s.accounts, payroll: s.payrolls, portfolio: s.portfolios, asset: s.assets, trade: s.trades, quote: s.prices, dividend: s.dividends, goal: s.goals, budget: s.budgets, recurring: s.recurrings, category: s.categories }[kind] || [];
    const r = (records.find(x => x.id === recordId) || {});
    const common = (body) => `<form id="entry-form" data-kind="${kind}" data-record="${esc(recordId || '')}"><div class="form-grid">${body}</div><div class="modal-footer"><button class="btn btn-soft" type="button" data-action="close-modal">Cancelar</button><button type="submit" class="btn btn-primary">${recordId ? 'Guardar cambios' : 'Guardar registro'}</button></div></form>`;
    switch (kind) {
        case 'movement': return { title: recordId ? 'Editar movimiento' : 'Nuevo movimiento', html: common(select('Tipo', 'kind', [opt('expense', 'Gasto', r.kind || 'expense'), opt('income', 'Ingreso', r.kind || 'expense'), opt('transfer', 'Transferencia entre mis cuentas', r.kind || 'expense')], 'id="movement-kind"') + field('Fecha', 'date', r.date || iso, 'date', 'required') + field('Importe (€)', 'amount', r.amount ?? '', 'number', 'min="0.01" step="0.01" required') + select('Cuenta de origen / destino del cobro', 'accountId', accountOptions(s, r.accountId), 'required') + select('Categoría (para ingresos o gastos)', 'categoryId', opt('', 'Sin categoría') + categoryOptions(s, r.categoryId)) + select('Cuenta de destino (solo transferencia)', 'toAccountId', opt('', 'Sin destino') + accountOptions(s, r.toAccountId)) + field('Concepto', 'description', r.description || '', 'text', 'required maxlength="120"') + desc('Las transferencias entre tus cuentas no se suman a ingresos ni gastos.')) };
        case 'account': return { title: recordId ? 'Editar cuenta' : 'Nueva cuenta', html: common(field('Nombre de la cuenta', 'name', r.name || '', 'text', 'required maxlength="70"') + select('Tipo de cuenta', 'kind', [opt('bank', 'Cuenta bancaria', r.kind), opt('cash', 'Efectivo', r.kind), opt('broker', 'Efectivo en bróker', r.kind), opt('debt', 'Préstamo / deuda', r.kind), opt('other', 'Otra', r.kind)]) + field('Saldo inicial (€; negativo para una deuda)', 'openingBalance', r.openingBalance ?? 0, 'number', 'step="0.01" required') + field('Fecha de apertura / saldo inicial', 'openingDate', r.openingDate || iso, 'date', 'required') + desc('El saldo inicial representa el saldo al inicio de la fecha elegida; las operaciones anteriores no alteran ese saldo. Los préstamos se anotan con saldo negativo. Transferir desde una deuda a un banco representa recibir el préstamo; transferir del banco a la deuda reduce lo pendiente. Los intereses son gastos.')) };
        case 'payroll': return { title: recordId ? 'Editar nómina' : 'Registrar nómina', html: common(field('Empresa', 'employer', r.employer || 'Repsol', 'text', 'required') + field('Fecha de cobro', 'date', r.date || iso, 'date', 'required') + select('Cuenta donde se ingresa el neto', 'accountId', accountOptions(s, r.accountId), 'required') + field('Salario bruto (€)', 'gross', r.gross ?? '', 'number', 'min="0" step="0.01" required') + field('Retenciones IRPF (€)', 'withholding', r.withholding ?? 0, 'number', 'min="0" step="0.01" required') + field('Seguridad Social (€)', 'social', r.social ?? 0, 'number', 'min="0" step="0.01" required') + field('Retribución flexible (€)', 'flex', r.flex ?? 0, 'number', 'min="0" step="0.01" required') + field('Neto ingresado (€)', 'net', r.net ?? '', 'number', 'min="0" step="0.01" required') + field('Notas (opcional)', 'note', r.note || '') + desc('Solo el neto se ingresa en la cuenta. La retribución flexible es informativa: si recibes acciones, usa una operación de entrega de acciones.')) };
        case 'portfolio': return { title: recordId ? 'Editar cartera' : 'Nueva cartera', html: common(field('Nombre de la cartera', 'name', r.name || '', 'text', 'required') + field('Plataforma / bróker', 'platform', r.platform || '', 'text', 'required')) };
        case 'asset': return { title: recordId ? 'Editar activo' : 'Nuevo activo', html: common(select('Cartera', 'portfolioId', portfolioOptions(s, r.portfolioId), 'required') + select('Tipo', 'kind', [opt('fund', 'Fondo de inversión', r.kind), opt('stock', 'Acción', r.kind), opt('crypto', 'Criptomoneda', r.kind)]) + field('Nombre completo', 'name', r.name || '', 'text', 'required') + field('Símbolo / código', 'symbol', r.symbol || '', 'text', 'required maxlength="25"') + field('Precio manual de referencia (€)', 'price', r.price ?? 0, 'number', 'min="0" step="any" required') + field('Fecha de valoración', 'priceDate', r.priceDate || iso, 'date', 'required') + desc('Los valores no se actualizan desde internet. Puedes crear nuevas valoraciones en Actualizar precio.')) };
        case 'trade': return { title: recordId ? 'Editar operación de inversión' : 'Compra, venta o entrega', html: common(select('Activo', 'assetId', assetOptions(s, r.assetId), 'required') + select('Tipo de operación', 'kind', [opt('buy', 'Compra (sale dinero de una cuenta)', r.kind), opt('sell', 'Venta (entra dinero en la cuenta)', r.kind), opt('grant', 'Entrega de acciones / retribución flexible (sin efectivo)', r.kind)]) + field('Fecha', 'date', r.date || iso, 'date', 'required') + field('Cantidad de títulos / participaciones', 'quantity', r.quantity ?? '', 'number', 'min="0.00000001" step="any" required') + field('Precio unitario (€)', 'unitPrice', r.unitPrice ?? '', 'number', 'min="0" step="any" required') + field('Comisiones (€)', 'fee', r.fee ?? 0, 'number', 'min="0" step="0.01" required') + select('Cuenta de efectivo (compra / venta)', 'accountId', opt('', 'Sin cuenta') + accountOptions(s, r.accountId)) + field('No vendible hasta (opcional)', 'unlockDate', r.unlockDate || '', 'date') + field('Notas', 'note', r.note || '') + desc('Las entregas de acciones no restan saldo bancario. Registra el valor de adquisición como coste, no como ganancia. El coste de las ventas se calcula por FIFO.')) };
        case 'quote': return { title: 'Actualizar valoración manual', html: common(select('Activo', 'assetId', assetOptions(s, r.assetId), 'required') + field('Fecha de valoración', 'date', r.date || iso, 'date', 'required') + field('Precio por unidad (€)', 'price', r.price ?? '', 'number', 'min="0" step="any" required') + desc('La valoración más reciente se mostrará en el patrimonio. Las valoraciones anteriores quedan en el histórico.')) };
        case 'dividend': return { title: recordId ? 'Editar dividendo' : 'Registrar dividendo', html: common(select('Activo', 'assetId', assetOptions(s, r.assetId), 'required') + select('Cuenta que recibe el cobro', 'accountId', accountOptions(s, r.accountId), 'required') + field('Fecha del cobro', 'date', r.date || iso, 'date', 'required') + field('Dividendo bruto (€)', 'gross', r.gross ?? '', 'number', 'min="0" step="0.01" required') + field('Retención (€)', 'tax', r.tax ?? 0, 'number', 'min="0" step="0.01" required') + field('Comisiones (€)', 'fee', r.fee ?? 0, 'number', 'min="0" step="0.01" required') + desc('El importe neto se suma a tu cuenta y al resultado de la inversión, pero no se introduce dos veces.')) };
        case 'goal': return { title: recordId ? 'Editar objetivo' : 'Nuevo objetivo', html: common(field('Nombre del objetivo', 'name', r.name || '', 'text', 'required') + field('Importe objetivo (€)', 'target', r.target ?? '', 'number', 'min="0.01" step="0.01" required') + field('Dinero ya asignado (€)', 'allocated', r.allocated ?? 0, 'number', 'min="0" step="0.01" required') + field('Fecha objetivo', 'deadline', r.deadline || '2028-12-31', 'date', 'required') + select('Tipo de meta', 'kind', [opt('vivienda', 'Vivienda', r.kind), opt('seguridad', 'Emergencia', r.kind), opt('moto', 'Vehículo / moto', r.kind), opt('inversion', 'Patrimonio invertido', r.kind), opt('otro', 'Otro', r.kind)]) + desc('El dinero asignado es orientativo y no se contabiliza de nuevo en tu patrimonio.')) };
        case 'budget': return { title: recordId ? 'Editar presupuesto' : 'Presupuesto por categoría', html: common(select('Categoría de gasto', 'categoryId', categoryOptions(s, r.categoryId, 'expense'), 'required') + field('Límite mensual (€)', 'amount', r.amount ?? '', 'number', 'min="0" step="0.01" required') + desc('Una categoría solo puede tener un presupuesto. Para modificarlo, selecciona su categoría.')) };
        case 'recurring': return { title: recordId ? 'Editar regla recurrente' : 'Nuevo gasto / ingreso recurrente', html: common(select('Tipo', 'kind', [opt('expense', 'Gasto', r.kind), opt('income', 'Ingreso', r.kind)]) + select('Cuenta', 'accountId', accountOptions(s, r.accountId), 'required') + select('Categoría', 'categoryId', categoryOptions(s, r.categoryId), 'required') + field('Concepto', 'description', r.description || '', 'text', 'required') + field('Importe (€)', 'amount', r.amount ?? '', 'number', 'min="0.01" step="0.01" required') + field('Día del mes', 'day', r.day ?? 1, 'number', 'min="1" max="31" step="1" required') + field('Fecha de inicio', 'startDate', r.startDate || iso, 'date', 'required') + select('Estado', 'active', [opt('true', 'Activo', String(r.active ?? true)), opt('false', 'Pausado', String(r.active ?? true))]) + desc('Genera automáticamente los vencimientos al abrir la web, sin duplicarlos. En meses cortos utiliza el último día.')) };
        case 'category': return { title: recordId ? 'Editar categoría' : 'Nueva categoría', html: common(field('Nombre', 'name', r.name || '', 'text', 'required') + select('Tipo', 'kind', [opt('expense', 'Gasto', r.kind), opt('income', 'Ingreso', r.kind)])) };
        default: return { title: 'Registro', html: 'Formulario no disponible' };
    }
}
export function quickReference(s) { return s.categories.map(c => `${c.name} (${c.kind})`).join(', '); }
